functions.params:
{
  "type": "object",
  "properties": {
    "reason": {
      "type": "string",
      "description": "Short qualification summary passed to the live closer"
    },
    "prospect_name": {
      "type": "string",
      "description": "Prospect first/full name if known or stated"
    },
    "confirmed_age": {
      "type": "string",
      "description": "Confirmed age of the prospect (e.g. \"71\")"
    },
    "medicare_status": {
      "type": "string",
      "description": "Confirmed Medicare status (e.g. \"Part A & B\", \"Part A\", \"Part B\")"
    },
    "hook_type": {
      "type": "string",
      "description": "Value proposition hook used on this call (e.g. \"Food & OTC Card\")"
    }
  },
  "required": [
    "reason"
  ]
}

{
  "type": "object",
  "properties": {
    "code": {
      "type": "string",
      "description": "VICIdial disposition status code (e.g. XFER, DQ, LANG, DNC, NI, NA, CALLBK, DEC)"
    },
    "notes": {
      "type": "string",
      "description": "Optional call summary note saved to the lead record"
    }
  },
  "required": [
    "code"
  ]
}
